def transform(g):
    g=[row[:] for row in g]; tracks=[1,4,7,10,13]
    cols={c:[r[c] for r in g] for c in tracks}
    order=sorted(tracks, key=lambda c: -cols[c][0] if False else -sum(1 for v in cols[c] if v==0))
